ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Status__c),
    OR(
        /* Terminal states — once set, Status cannot change */
        ISPICKVAL(PRIORVALUE(Status__c), 'Effective'),
        ISPICKVAL(PRIORVALUE(Status__c), 'Superseded'),
        /* Submitted cannot revert to Draft */
        AND(ISPICKVAL(PRIORVALUE(Status__c), 'Submitted'),  ISPICKVAL(Status__c, 'Draft')),
        /* Approved cannot revert to Draft or Submitted */
        AND(ISPICKVAL(PRIORVALUE(Status__c), 'Approved'),   ISPICKVAL(Status__c, 'Draft')),
        AND(ISPICKVAL(PRIORVALUE(Status__c), 'Approved'),   ISPICKVAL(Status__c, 'Submitted'))
    )
)
